/* updateSellerMdCtMbrCmpyInfoUsr */
UPDATE ICOMLUSR
SET
	USER_NAME_LOC	= #{st_user_name_loc},
	PHONE_NUMBER	= #{st_phone_number},
	MOBILE_PHONE	= #{st_mobile_phone},
	EMAIL			= #{st_email}
WHERE USER_ID		= #{st_user_id}
AND COM_CODE		= #{st_com_code}


/* updateSellerMdCtBankAccountNoinfo */
UPDATE ACNTSUPL
SET
	BANK_ACCOUNT_NO = #{st_hash_bank_account_no}
WHERE SUPPLIER				= #{st_com_code}
